SELECT CASE WHEN c.age >= 71 THEN 'high' WHEN c.age >= 31 THEN 'mid' ELSE 'low' END AS age_bucket, MAX(s.monthly_fee) - MIN(s.monthly_fee) AS monthly_fee_range FROM subscriptions s INNER JOIN customers c ON s.customer_id = c.id WHERE c.segment IN ('Corporate', 'SMB') GROUP BY CASE WHEN c.age >= 71 THEN 'high' WHEN c.age >= 31 THEN 'mid' ELSE 'low' END HAVING MAX(s.monthly_fee) - MIN(s.monthly_fee) >= 52 ORDER BY monthly_fee_range DESC
